// https://atcoder.jp/contests/abs/fasks/arc089_a

fn main() {
    input! {
        n: usize,
        t: usize,
        mut ab: [(usize, usize); n],  // Vec
    }

    // sort ab
    ab.sort_unstable_by(|(a0,_),(a1,_)|a0.cmp(a1));
    let ab = ab;

    // compute maximum manzokukans without the last order
    let mut table :Vec<Vec<usize>> = vec![vec![0;t];n];
    for i in 0..n {
        for j in 0..t {
            let (a, b) = ab[i];
            // The case where meal No.i is not eaten
            let manzoku0 = if i > 0 {
                table[i-1][j]
            } else {
                0
            };
            // The case where meal No.i is eaten
            let manzoku1 = if i > 0 && j >= a {
                table[i-1][j-a] + b
            } else if j >= a {
                b
            } else {
                0
            };

            table[i][j] = manzoku0.max(manzoku1);
        }
    }
    let table = table;

    let mut maxmanzoku = 0;
    for i in 0..n {
        let (_, b) = ab[i];
        for j in 0..t {
            let withoutlast = if i > 0 {
                table[i-1][j]
            } else {
                0
            };
            let manzoku = withoutlast + b;
            maxmanzoku = maxmanzoku.max(manzoku);
        }
    }

    println!("{}", maxmanzoku);
}

