	use std::io::Read;
	std::io::stdin().read_to_string(&mut s).unwrap();
	let mut s = s.split_whitespace();
	let n: usize = s.next().unwrap().parse().unwrap();
	let k: usize = s.next().unwrap().parse().unwrap();
	let p: Vec<i32> = s.by_ref().take(3).map(|a| a.parse().unwrap()).collect();
	let t: Vec<_> = s.next().unwrap().chars().collect();
	let mut dp = vec![vec![0; 3]; n];
	for m in 0..k {
		for hand in 0..3 {
			dp[m][hand] = match hand {
				0 if t[m] == 's' => p[0],
				1 if t[m] == 'p' => p[1],
				2 if t[m] == 'r' => p[2],
				_ => 0,
			};
		}
		for i in (1..).map(|i| m + i * k).take_while(|&i| i < n) {
			for last in 0..3 {
				for hand in 0..3 {
					if last == hand {
						continue;
					}
					let t = match hand {
						0 if t[i] == 's' => p[0],
						1 if t[i] == 'p' => p[1],
						2 if t[i] == 'r' => p[2],
						_ => 0,
					};
					if dp[i][hand] < t + dp[i - k][last] {
						dp[i][hand] = t + dp[i - k][last];
					}
				}
			}
		}
	}
	println!("{}", dp.iter().rev().take(k).fold(0, |r, a| { r + std::cmp::max(std::cmp::max(a[0], a[1]), a[2]) }));
}

