fn main() {
    let n: usize = read();
    let m: usize = read();
    let p: i64 = read();

    let mut ab: Vec<Vec<(usize, i64)>> = vec![vec![]; n];
    let mut ba: Vec<Vec<usize>> = vec![vec![]; n];
    for _ in 0..m {
        let a: usize = read();
        let b: usize = read();
        let c: i64 = read();
        ab[a-1].push((b-1, p-c));
        ba[b-1].push(a-1);
    }

    let mut que = VecDeque::new();
    let mut used = vec![false; n];
    que.push_back(n-1);
    used[n-1] = true;
    while let Some(q) = que.pop_front() {
        for i in &ba[q] {
            if !used[*i] {
                used[*i] = true;
                que.push_back(*i);
            }
        }
    }
    let mut used2 = vec![false; n];
    que.push_back(0);
    used2[0] = true;
    while let Some(q) = que.pop_front() {
        for &(i, _) in &ab[q] {
            if !used2[i] {
                used2[i] = true;
                que.push_back(i);
            }
        }
    }

    let mut d: Vec<i64> = vec![0; n];
    let mut ok = true;
    for k in 0..n {
        for i in 0..n {
            if !used[i] || !used2[i] {
                continue;
            }
            for &(to, cost) in &ab[i] {
                if d[to] > d[i] + cost {
                    d[to] = d[i] + cost;

                    if k == n-1 {
                        ok = false;
                    }
                }
            }
        }
    }
    if !ok {
        println!("-1");
        return;
    }

    let INF = 1_i64 << 60;
    for i in 0..n {
        d[i] = INF;
    }
    d[0] = 0;
    loop {
        let mut update = false;
        for i in 0..n {
            if !used[i] || !used2[i] {
                continue;
            }
            for &(to, cost) in &ab[i] {
                if d[i] != INF && d[to] > d[i] + cost {
                    d[to] = d[i] + cost;
                    update = true;
                }
            }
        }
        if !update {
            break;
        }
    }
    println!("{}", std::cmp::max(0, -d[n-1]));
