    }
    // n choose r の合計、ただしr=a,bを除く。
    // n choose r = fact[n] * modInv(fact[n-r])*modInv(fact[r])
    // let mut fact = vec![1i64; n + 1];
    //  let mut ifact = vec![1i64; n + 1];
    let mut fact = 1;
    let mut fact_a = 0;
    let mut fact_b = 0;
    let mut fact_na = 0;
    let mut fact_nb = 0;
    for i in 1i64..=b as i64 {
        fact = fact * i % MOD;
        //println!("fact[{}]={}", i, fact);
        match i {
            i if i == a => {
                fact_a = fact;
            }
            i if i == b => {
                fact_b = fact;
            }
            _ => (),
        }
    }
    fact = 1;
    for i in ((n - b) as i64..=n as i64).rev() {
        fact = fact * i % MOD;
        match i {
            i if i == n - a + 1 => {
                fact_na = fact;
            }
            i if i == n - b + 1 => {
                fact_nb = fact;
            }
            _ => (),
        }
    }

    //println!("{},{},{},{}", fact_a, fact_b, fact_na, fact_nb);
    let mut ans = modPow(2, n as i64) - 1;
    let choose_na = fact_na * modInv(fact_a) % MOD;
    let choose_nb = fact_nb * modInv(fact_b) % MOD;
    ans = (ans + MOD + MOD - choose_na - choose_nb) % MOD;
    println!("{}", ans);
}

fn modPow(x: i64, a: i64) -> i64 {
    if a == 0 {
        1
    } else {
        if a % 2 != 0 {
            modPow(x, a - 1) * x % MOD
        } else {
            let y = modPow(x, a / 2);
            y * y % MOD
        }
    }
}
fn modInv(x: i64) -> i64 {
    modPow(x, MOD - 2) % MOD
}

