                }
                group[i][j] = Some((i_origin, j_origin));
                let nexts = [
                    (i.wrapping_sub(1), j),
                    (i, j.wrapping_sub(1)),
                    (i + 1, j),
                    (i, j + 1),
                ];
                for &(i_next, j_next) in &nexts {
                    if i_next < h
                        && j_next < w
                        && group[i_next][j_next].is_none()
                        && ss[i][j] != ss[i_next][j_next]
                    {
                        deque.push_back((i_next, j_next));
                    }
                }
            }
        }
