fn main() {
    input! {
        n: usize, m: usize,
        mut arr: [usize; n],
        rep: [(usize, usize); m],
    }

    arr.sort();

    let mut bset: BTreeMap<usize, usize> = BTreeMap::new();
    for &(b, c) in &rep {
        if bset.contains_key(&c) {
            let bb = bset.get_mut(&c).unwrap();
            *bb += b;
        } else {
            bset.insert(c, b);
        }
    }

    let mut cursor: usize = 0;
    for (&c, &b) in bset.iter().rev() {
        let m = std::cmp::min(n, b+cursor);
        if arr[m-1] >= c {
            for i in cursor..m {
                if arr[i] >= c { break; }
                arr[i] = c;
            }
            break;
        } else {
            for i in cursor..m { arr[i] = c; }
            cursor = m;
        }
    }

    println!("{}", arr.iter().sum::<usize>() );
