    A = [int(a) for a in input().split()]
    mixed = False
    for i in range(1, N):
        if A[i] % 2 != A[0] % 2:
            mixed = True
            break
    flag = 0
    if mixed:
        for i in range(N):
            if A[i] % 2 == 1:
                flag = i
                break
    Tentative = [0] * N
    for i in range(N-1):
        Tentative[(flag + i + 1) % N] += A[(flag + i) % N] - Tentative[(flag + i) % N]
        Tentative[(flag + i) % N] *= 2
    Tentative[(flag + N - 1) % N] *= 2
    dam = (Tentative[flag] + Tentative[flag - 1]) // 2
    diff = A[flag - 1] - dam
    if diff != 0:
        for i in range(N//2):
            Tentative[(flag + i) % N] += diff * (-1) ** (i % 2)
            Tentative[(flag - 1 - i) % N] += diff * (-1) ** (i % 2)
        Tentative[(flag + N // 2) % N] += diff * (-1) ** ((N//2) % 2) 

    print(" ".join(map(str, Tentative)))

    return 0

