const modulus :usize = 1000000007;

fn main(){
    let mut stdin = io::stdin();
    let mut lines_str = String::new();
    let _ = stdin.read_to_string(&mut lines_str);
    let lines_vec = lines_str.lines().collect::<Vec<&str>>();
    let line0_vec = lines_vec[0].split(' ').collect::<Vec<&str>>();
    let n :usize = line0_vec[0].trim().parse().unwrap(); //n >= 3
    let mut k :usize = line0_vec[1].trim().parse().unwrap(); //k >= 2

    // prepare a table of factorials
    let mut fac_vec :Vec<usize> = Vec::new();
    let mut fac_inv_vec :Vec<usize> = Vec::new();
    fac_vec.push(1);
    fac_inv_vec.push(1);
    for i in 1..(n+1) {
        fac_vec.push((i*fac_vec[i-1]) % modulus);
        fac_inv_vec.push(mod_inv(fac_vec[i]));
    }
    let fac_vec = fac_vec;
    let fac_inv_vec = fac_inv_vec;

    // normalize k
    if k >= n {
        k = n - 1;
    }
    let k = k;

    let mut total = 0;
    for i in 0..(k+1) {
        let mut thispart = (fac_vec[n] * fac_inv_vec[i]) % modulus;
        thispart = (thispart * fac_inv_vec[n-i]) % modulus;
        thispart = (thispart * fac_vec[n-1]) % modulus;
        thispart = (thispart * fac_inv_vec[n-i-1]) % modulus;
        thispart = (thispart * fac_inv_vec[i]) % modulus;
        total = (total + thispart) % modulus;
    }

    println!("{}", total);
}

// https://math.nakaken88.com/textbook/cp-modulo-operation-inverse-element/
fn mod_pow(base :usize, index :usize) -> usize {
    if index == 0 {
        return 1;
    } else if index == 1 {
        return base % modulus;
    } else {
        if index % 2 == 0 {
            let tmp = mod_pow(base, index/2);
            return (tmp * tmp) % modulus;
        } else {
            let tmp = mod_pow(base, index/2);
            return (((tmp * tmp) % modulus) * base ) % modulus;
        }
    }
}

fn mod_inv(x :usize) -> usize {
    return mod_pow(x, modulus-2);
}
