        let q = in_n / p;
        let mut n = in_n;
        let mut m = in_n;

        while n % p == 0 {
            n /= p;
        }

        while m % q == 0 {
            m /= q;
        }

        if n % p == 1 {
            count += 1;
        }

        if m != q && p % q == 1 {
            count += q;
        }
    }

    for p in 2..=in_n {
        if p * p > in_n {
            break;
        }

        if in_n % p != 1 {
            continue;
        }

        let q = (in_n - 1) / p;

        if p == q {
            count += 1;
        } else {
            count += 2;
        }
    }

    println!("{}", count + 2);
}

